class Interpolation:
    _EPSILON = 1e-10

    @staticmethod
    def _linear_interp_1d(x, y, xi):
        for i in range(len(x) - 1):
            if x[i] - Interpolation._EPSILON <= xi <= x[i + 1] + Interpolation._EPSILON:
                numerator = (xi - x[i]) * (y[i + 1] - y[i])
                denominator = (x[i + 1] - x[i])
                if abs(denominator) < Interpolation._EPSILON:
                    return y[i]
                return y[i] + numerator / denominator
        return None

    @staticmethod
    def _bilinear_interp_2d(x, y, z, xi, yi):
        for i in range(len(x) - 1):
            if x[i] - Interpolation._EPSILON <= xi <= x[i + 1] + Interpolation._EPSILON:
                for j in range(len(y) - 1):
                    if y[j] - Interpolation._EPSILON <= yi <= y[j + 1] + Interpolation._EPSILON:
                        x_i = x[i]
                        x_ip1 = x[i + 1]
                        y_j = y[j]
                        y_jp1 = y[j + 1]
                        dx = x_ip1 - x_i
                        dy = y_jp1 - y_j
                        if abs(dx) < Interpolation._EPSILON or abs(dy) < Interpolation._EPSILON:
                            continue
                        z00 = z[i][j]
                        z01 = z[i][j + 1]
                        z10 = z[i + 1][j]
                        z11 = z[i + 1][j + 1]
                        weight_xi_left = (x_ip1 - xi) / dx
                        weight_xi_right = (xi - x_i) / dx
                        weight_yi_down = (y_jp1 - yi) / dy
                        weight_yi_up = (yi - y_j) / dy
                        return (z00 * weight_xi_left * weight_yi_down +
                                z10 * weight_xi_right * weight_yi_down +
                                z01 * weight_xi_left * weight_yi_up +
                                z11 * weight_xi_right * weight_yi_up)
                break
        return None

    @classmethod
    def interpolate_1d(cls, x, y, x_interp):
        return [
            cls._linear_interp_1d(x, y, xi)
            for xi in x_interp
            if cls._linear_interp_1d(x, y, xi) is not None
        ]

    @classmethod
    def interpolate_2d(cls, x, y, z, x_interp, y_interp):
        return [
            cls._bilinear_interp_2d(x, y, z, xi, yi)
            for xi, yi in zip(x_interp, y_interp)
            if cls._bilinear_interp_2d(x, y, z, xi, yi) is not None
        ]
